\begin{exercise}[Parallel tensor fields]
\label{prob:parallel-tensor-fields}
\dcref{ch4:4-12}
\uses{prop:parallel-field-characterization}
Prove Proposition 4.36 (a vector or tensor field $A$ is parallel if and only if $\nabla A = 0$).
\end{exercise}

